import zlib,re

def decode16(h):
    s=h.decode('latin1')
    s=re.sub(r'\s+','',s)
    if not s: return ''
    out=[]
    for i in range(0,len(s),4):
        c=int(s[i:i+4],16)
        u=c+0x1d
        if 0x7e0 <= c <= 0x7ff:   # icon/symbol fn region
            u=c-0x7e0+0x2766       # guess decorative char; mark it
        out.append(chr(u))
    return ''.join(out)

def text_of(fname):
    data=open(fname,'rb').read()
    full=[]
    for m in re.finditer(rb'stream\r?\n(.*?)endstream',data,re.S):
        try: s=zlib.decompress(m.group(1))
        except Exception: continue
        for mm in re.finditer(rb'BT(.*?)ET',s,re.S):
            blk=mm.group(1)
            parts=[]
            for pm in re.finditer(rb'\[(.*?)\]\s*T[\w\']*',blk,re.S):
                arr=pm.group(1)
                for hm in re.finditer(rb'<([0-9A-Fa-f\s]+)>',arr):
                    parts.append(decode16(hm.group(1)))
            if parts:
                full.append(''.join(parts))
        # also non-BT text ops
        for pm in re.finditer(rb'<([0-9A-Fa-f\s]+)>\s*Tj',s):
            full.append(decode16(pm.group(1)))
    return ''.join(full)

open('/tmp/opencode/buyerA.txt','w').write(text_of('loi_buyer_a_asset_purchase.pdf'))
open('/tmp/opencode/buyerB.txt','w').write(text_of('loi_buyer_b_stock_purchase.pdf'))
EOF
